.segmented {
  display: inline-flex;
  padding: var(--space-2xs);
  /* The same grey a quiet button fills itself with, and for the same reason:
   * this rail used to be `light-dark(--muted, --card)`, and --muted IS the page,
   * so on a page the rail was the exact colour of the page — 1.00:1, no control
   * at all — while on a card it read fine. One grey, both surfaces, both
   * themes, and it is the grey the rest of the control family already uses. */
  background: var(--surface-contrast);
  border-radius: var(--control-radius);
}
.segmented-option {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  min-block-size: calc(var(--control-height) - var(--space-2xs) * 2);
  border: none;
  background: transparent;
  color: var(--muted-foreground);
  font-family: inherit;
  /* Same type as the rest of the control family (Button/Select) so a segmented
   * toggle next to them reads as one system, not a smaller sibling. */
  font-size: var(--control-font-size);
  /* ONE WEIGHT FOR EVERY SEGMENT, selected or not. `medium` on the selected one
   * only made the label WIDER the moment it was chosen, so each segment and the
   * whole control resized on every click and the row jumped under the pointer
   * (owner, 2026-08-24). Selection is said by the pill and the brand ink, which
   * cost no width. */
  font-weight: var(--font-weight-medium);
  padding-block: 0;
  padding-inline: var(--space-4);
  border-radius: calc(var(--control-radius) - var(--space-2xs));
  cursor: pointer;
  white-space: nowrap;
  transition: color var(--duration-fast), background var(--duration-fast);
}
.segmented[data-size='sm'] .segmented-option { min-block-size: calc(var(--control-height-sm) - var(--space-2xs) * 2); padding-block: 0; padding-inline: var(--space-3); font-size: var(--font-sm); }
.segmented[data-size='lg'] .segmented-option { min-block-size: calc(var(--control-height-lg) - var(--space-2xs) * 2); padding-block: 0; padding-inline: var(--space-6); font-size: var(--control-font-size-lg); }
.segmented-option:hover { color: var(--foreground); }
/* Pressed: the segment tints rather than only darkening its label, so the press
 * is legible on a control whose resting state is bare text. */
.segmented-option:active { background: var(--surface-contrast-active); color: var(--foreground); }
.segmented-option:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: calc(var(--ring-offset) * -1);
}
/* Selected = a lifted pill AND brand-coloured text.
 *
 * The lift alone was the whole signal until 2026-08-03, which is the iOS/shadcn
 * convention and reads fine in isolation — but on a page whose primary action is
 * a filled brand button, a grey-on-white pill is the quietest thing in the row
 * and the selection has to be looked for. Text only, not a filled pill: a second
 * solid brand block would compete with the button for "the thing to press". */
.segmented-option[data-selected] {
  background: light-dark(var(--background), var(--popover));
  color: var(--primary-accent);
}

/* On a --muted surface (app main column, PageHeader) the fills invert in light
 * so the control still reads: white track, grey selected pill. In dark, --muted
 * and --background collapse, so the same --card/--popover elevation is used as
 * the base surface. No border, no shadow. */
.segmented[data-surface="muted"] { background: light-dark(var(--background), var(--card)); }
.segmented[data-surface="muted"] .segmented-option[data-selected] { background: light-dark(var(--muted), var(--popover)); }

import './SegmentedControl.css'
import { useRef, type KeyboardEvent } from 'react'
import { cn } from '../lib/cn'
import { type Option } from '../lib/option'
import { Icon, type IconName } from '../Icon'

/** A segment: the shared <Option> plus the mark this control draws beside the
 *  label (a sun/moon for a light/dark toggle). Named SegmentOption, not
 *  Segment — DonutChart exports that name for a share of a ring. */
export type SegmentOption<V extends string> = Option<V> & { icon?: IconName }

type Props<V extends string> = {
  value: V
  onChange: (value: V) => void
  options: readonly SegmentOption<V>[]
  /** Accessible name for the group. */
  label: string
  size?: 'sm' | 'md' | 'lg'
  /** Which surface the control sits on, so its fills invert to stay visible.
   *  `base` (default): grey track on a white/card surface, white selected pill.
   *  `muted`: white track on a grey (--muted) surface, grey selected pill. */
  surface?: 'base' | 'muted'
  className?: string
}

/* A single-choice toggle rendered as adjacent segments — a compact radio group
 * for switching a view (List / Board, Day / Week / Month). Uses the radiogroup
 * pattern (Arrow keys move and select); distinct from <Tabs>, which navigates
 * between panels, and from <Select>, which is for longer lists. 
   *
   * Copy: one or two words per segment, parallel with each other. They sit side by
   * side, so a long one makes every other look empty.
   */
export function SegmentedControl<V extends string>({ value, onChange, options, label, size = 'md', surface = 'base', className }: Props<V>) {
  const ref = useRef<HTMLDivElement>(null)

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(e.key)) return
    e.preventDefault()
    const i = options.findIndex((o) => o.value === value)
    let next = i
    if (e.key === 'ArrowRight') next = (i + 1) % options.length
    else if (e.key === 'ArrowLeft') next = (i - 1 + options.length) % options.length
    else if (e.key === 'Home') next = 0
    else if (e.key === 'End') next = options.length - 1
    onChange(options[next].value)
    ref.current?.querySelectorAll<HTMLButtonElement>('[role="radio"]')[next]?.focus()
  }

  return (
    // eslint-disable-next-line jsx-a11y/interactive-supports-focus -- radiogroup uses roving tabindex on its radios; the group is not itself a focus target
    <div ref={ref} className={cn('segmented', className)} role="radiogroup" aria-label={label} data-size={size} data-surface={surface} onKeyDown={onKeyDown}>
      {options.map((opt) => {
        const selected = opt.value === value
        return (
          <button
            key={opt.value}
            type="button"
            role="radio"
            aria-checked={selected}
            tabIndex={selected ? 0 : -1}
            className="segmented-option"
            data-selected={selected || undefined}
            onClick={() => onChange(opt.value)}
          >
            {opt.icon && <Icon name={opt.icon} size="sm" />}
            {opt.label}
          </button>
        )
      })}
    </div>
  )
}
